// 名称：油价小组件（优化版 - 带更新时间）
// 作者：haoyu592
// 更新时间：2026-09-17
// 描述：显示当地92#/95#/98#/0#柴油实时油价，必须配置省份

// 配置说明：首次使用必须在Scriptable App内运行并配置省份

const DEFAULTS = {
  province: null, // 必须配置省份
  refreshHours: 4 // 默认刷新频率（小时）
};

// 内嵌原图：图标无需联网下载；仅油价和调价信息需要网络。
// 原图来源：https://raw.githubusercontent.com/haoyu592/DSbox/main/Old/Sinopec1.png
const SINOPEC_LOGO_BASE64 = "";

// 2026年成品油调价窗口（按公开日历更新）
const ADJUSTMENT_SCHEDULE = {
  2026: [
    "2026-01-06", "2026-01-20", "2026-02-03", "2026-02-24", "2026-03-09",
    "2026-03-23", "2026-04-07", "2026-04-21", "2026-05-08", "2026-05-21",
    "2026-06-04", "2026-06-18", "2026-07-03", "2026-07-17", "2026-07-31",
    "2026-08-14", "2026-08-28", "2026-09-11", "2026-09-24", "2026-10-15",
    "2026-10-29", "2026-11-12", "2026-11-26", "2026-12-10", "2026-12-24"
  ]
};

// 主函数
async function main() {
  const widget = new ListWidget();
  
  try {
    // 获取配置
    const config = await getConfig();
    if (!config || !config.province) {
      throw new Error("请先配置省份");
    }
    
    const provinceId = cityToId(config.province);
    if (!provinceId) {
      throw new Error(`无效省份: ${config.province}`);
    }
    
    // 设置背景和颜色主题
    setupAppearance(widget); // 确保调用设置外观
    
    // 获取油价数据
    const oilData = await fetchOilPrice(provinceId);
    
    // 添加标题行
    const titleStack = widget.addStack();
    titleStack.centerAlignContent();
    const titleText = titleStack.addText(`今日油价 · ${config.province}`);
    titleText.font = Font.boldSystemFont(18);
    titleText.textColor = getTextColor(); // 使用主题文字颜色
    widget.addSpacer(8); // 标题和内容之间的间距
    
    // 构建内容区域
    const contentStack = widget.addStack();
    contentStack.spacing = 8;
    
    // 左侧油价网格 - 增加权重，占用更多空间
    const gridStack = contentStack.addStack();
    gridStack.layoutVertically();
    gridStack.size = new Size(0, 0); // 自动调整大小
    addOilGrid(gridStack, oilData);
    
    // 右侧图标区域 - 减少宽度
    const rightStack = contentStack.addStack();
    rightStack.layoutVertically();
    rightStack.size = new Size(120, 0); // 缩小宽度为120
    
    // 中石化Logo
    await addLogo(rightStack);
    
    // 添加油价调整时间显示
    widget.addSpacer(8);
    await addUpdateTime(widget);
    
   } catch (error) {
     //错误处理
     const errorStack = widget.addStack();
    errorStack.layoutVertically();
    errorStack.addSpacer();
    
    const errorText = errorStack.addText(error.message);
    errorText.font = Font.mediumSystemFont(14);
    errorText.textColor = Color.red();
    errorText.centerAlignText();
    
    if (error.message.includes("配置")) {
      const setupText = errorStack.addText("在App内运行配置");
      setupText.font = Font.footnote();
      setupText.textColor = Color.blue();
      setupText.centerAlignText();
    }
    
    errorStack.addSpacer();
  }
  
  // 使用配置的刷新频率（小时）
  const config = await getConfig();
  const refreshMillis = (config?.refreshHours || DEFAULTS.refreshHours) * 60 * 60 * 1000;
  widget.refreshAfterDate = new Date(Date.now() + refreshMillis);
  
  Script.setWidget(widget);
  Script.complete();
  return widget;
}

// 添加油价调整时间和预测幅度显示
async function addUpdateTime(widget) {
  const updateStack = widget.addStack();
  updateStack.layoutVertically();
  updateStack.centerAlignContent();
  
  const html = await fetchOilAdjustmentPage();
  const nextAdjustInfo = getNextOilPriceAdjustmentInfo(html);
  const timeString = nextAdjustInfo ? formatAdjustmentTime(nextAdjustInfo.date) : "暂未获取";
  const sourceLabel = nextAdjustInfo && nextAdjustInfo.source !== "website"
    ? (nextAdjustInfo.source === "cache" ? "（缓存）" : "（本地日历）") : "";
  
  // 显示下次调价时间
  const timeText = updateStack.addText(`下次调价: ${timeString}${sourceLabel}`);
  timeText.font = Font.systemFont(12);
  timeText.textColor = Color.gray();
  timeText.centerAlignText();
  
  // 获取并显示调价幅度预测
  const adjustmentPrediction = nextAdjustInfo && nextAdjustInfo.source === "website"
    ? getOilPriceAdjustmentPrediction(html) : null;
  if (adjustmentPrediction) {
    updateStack.addSpacer(2);
    const predictionText = updateStack.addText(adjustmentPrediction);
    predictionText.font = Font.systemFont(11);
    
    // 根据预测方向设置颜色
    if (adjustmentPrediction.includes("上调")) {
      predictionText.textColor = Color.red();
    } else if (adjustmentPrediction.includes("下调")) {
      predictionText.textColor = Color.green();
    } else {
      predictionText.textColor = Color.orange();
    }
    predictionText.centerAlignText();
  }
}

// 日期统一按北京时间解释；date 保存真正生效的瞬间（当日24时 = 次日0时）。
function beijingDate(date) {
  return new Date(date.getTime() + 8 * 60 * 60 * 1000);
}

async function fetchOilAdjustmentPage() {
  try {
    // 沿用网站可用的 HTTP 地址，其 HTTPS 证书目前不匹配域名。
    const req = new Request("http://www.qiyoujiage.com/");
    req.timeoutInterval = 12;
    const html = await req.loadString();
    if (req.response && req.response.statusCode !== 200) return "";
    return html;
  } catch (e) {
    console.error(`调价信息获取失败: ${e}`);
    return "";
  }
}

function oilPageText(html) {
  return html.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, "")
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, "")
    .replace(/<[^>]+>/g, "").replace(/&nbsp;|&#160;/gi, " ")
    .replace(/\s+/g, "");
}

function parseWebsiteAdjustment(html, now = new Date()) {
  const text = oilPageText(html);
  const match = text.match(/下次油价(?:调整(?:时间)?(?:为|是|将在)?)?[:：]?(?:(\d{4})年)?(\d{1,2})月(\d{1,2})日(\d{1,2})(?:[:：](\d{2})|时(?:(\d{1,2})分)?)(?:调整|进行)?/);
  if (!match) return null;
  const current = beijingDate(now);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const hour = Number(match[4]);
  const minute = Number(match[5] || match[6] || 0);
  let year = match[1] ? Number(match[1]) : current.getUTCFullYear();
  // 无年份时只允许12月到1月的跨年，不把过期公告自动挪到明年。
  if (!match[1] && current.getUTCMonth() === 11 && month === 1) year++;
  const calendarDate = new Date(Date.UTC(year, month - 1, day));
  if (calendarDate.getUTCFullYear() !== year || calendarDate.getUTCMonth() !== month - 1 ||
      calendarDate.getUTCDate() !== day || hour > 24 || minute > 59 ||
      (hour === 24 && minute !== 0)) return null;
  const date = new Date(Date.UTC(year, month - 1, day, hour - 8, minute));
  const remaining = date.getTime() - now.getTime();
  if (remaining <= 0 || remaining > 45 * 86400000) return null;
  return { date, source: "website" };
}

function adjustmentCache(info, now) {
  try {
    const fm = FileManager.local();
    const path = fm.joinPath(fm.documentsDirectory(), "oilWidgetAdjustmentCache.json");
    if (info) {
      fm.writeString(path, JSON.stringify({ date: info.date.toISOString() }));
    } else if (fm.fileExists(path)) {
      const date = new Date(JSON.parse(fm.readString(path)).date);
      const remaining = date.getTime() - now.getTime();
      if (remaining > 0 && remaining <= 45 * 86400000) return { date, source: "cache" };
    }
  } catch (e) {
    console.error(`调价缓存读写失败: ${e}`);
  }
  return null;
}

function getNextOilPriceAdjustmentInfo(html = "", now = new Date()) {
  const online = parseWebsiteAdjustment(html, now);
  if (online) {
    adjustmentCache(online, now);
    return online;
  }
  const cached = adjustmentCache(null, now);
  if (cached) return cached;
  const currentYear = beijingDate(now).getUTCFullYear();
  // 包括上一年12月31日24时的边界。
  for (const year of [currentYear - 1, currentYear, currentYear + 1]) {
    for (const dateStr of ADJUSTMENT_SCHEDULE[year] || []) {
      const [y, m, d] = dateStr.split("-").map(Number);
      const date = new Date(Date.UTC(y, m - 1, d + 1, -8));
      if (date > now) return { date, source: "schedule" };
    }
  }
  // 没有可靠日期时不再用“加10个自然日”猜测。
  return null;
}


// 获取油价调整幅度预测 - 使用网站解析实现
function getOilPriceAdjustmentPrediction(html) {
  try {
    html = oilPageText(html);
    
    // 提取方向
    const directionMatch = html.match(/预计(上调|下调|搁浅)/);
    
    // 提取吨幅度
    const tonMatch = html.match(/预计(?:上调|下调|搁浅)(?:油价)?(\d+)元\/吨/);
    
    // 提取升范围
    const rangeMatch = html.match(/[（(](-?\d+\.\d+元\/升[-~～至]－?-?\d+\.\d+元\/升)[）)]/);
    
    let prediction = "";
    
    if (directionMatch && directionMatch[1]) {
      const direction = directionMatch[1];
      let ton = tonMatch ? tonMatch[1] + "元/吨 " : "";
      let range = rangeMatch ? rangeMatch[1] : "";
      
      if (direction === "搁浅") {
        prediction = "预测搁浅或微调";
      } else {
        prediction = `预测${direction} ${ton}${range}`;
      }
    }
    
    if (prediction) {
      return prediction.trim();
    }
    
  } catch (e) {
    console.error(`预测获取失败: ${e}`);
  }
  
  return null;
}

// 按北京时间的日历日期判断今晚/明晚，午夜统一显示为前一天24:00。
function formatAdjustmentTime(date, now = new Date()) {
  const local = beijingDate(date);
  const midnight = local.getUTCHours() === 0 && local.getUTCMinutes() === 0;
  const display = midnight ? new Date(local.getTime() - 86400000) : local;
  const today = beijingDate(now);
  const diffDays = (Date.UTC(display.getUTCFullYear(), display.getUTCMonth(), display.getUTCDate()) -
    Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate())) / 86400000;
  const month = String(display.getUTCMonth() + 1).padStart(2, "0");
  const day = String(display.getUTCDate()).padStart(2, "0");
  const time = midnight ? "24:00" : `${String(local.getUTCHours()).padStart(2, "0")}:${String(local.getUTCMinutes()).padStart(2, "0")}`;
  const label = `${month}/${day}`;
  if (midnight && diffDays === 0) return `今晚(${label}) ${time}`;
  if (midnight && diffDays === 1) return `明晚(${label}) ${time}`;
  const weekdays = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"];
  return diffDays >= 0 && diffDays <= 7
    ? `${weekdays[display.getUTCDay()]}(${label}) ${time}` : `${label} ${time}`;
}

// 获取主题文字颜色
function getTextColor() {
  return Color.dynamic(Color.black(), Color.white()); // 使用动态颜色
}

// 获取配置（必须配置省份）
async function getConfig() {
  // 1. 尝试获取小组件参数
  if (args.widgetParameter) {
    return {
      province: args.widgetParameter,
      refreshHours: DEFAULTS.refreshHours
    };
  }
  
  // 2. 尝试从本地存储获取
  const localConfig = await loadConfig();
  if (localConfig && localConfig.province) {
    // 兼容旧配置（添加默认刷新频率）
    if (localConfig.refreshHours === undefined) {
      localConfig.refreshHours = DEFAULTS.refreshHours;
    }
    return localConfig;
  }
  
  // 3. 都没有则返回null（强制配置）
  return null;
}

// 从本地存储加载配置
async function loadConfig() {
  const fm = FileManager.local();
  const path = fm.joinPath(fm.documentsDirectory(), "oilWidgetConfig.json");
  
  if (fm.fileExists(path)) {
    try {
      const data = fm.readString(path);
      return JSON.parse(data);
    } catch (e) {
      return null;
    }
  }
  return null;
}

// 保存配置到本地存储
async function saveConfig(province, refreshHours) {
  const fm = FileManager.local();
  const path = fm.joinPath(fm.documentsDirectory(), "oilWidgetConfig.json");
  const config = { province, refreshHours };
  fm.writeString(path, JSON.stringify(config));
}

// 省份名称转ID
function cityToId(provinceName) {
  const provinceMap = {
    "北京": "11", "天津": "12", "河北": "13", "山西": "14", "内蒙古": "15",
    "辽宁": "21", "吉林": "22", "黑龙江": "23", "上海": "31", "江苏": "32",
    "浙江": "33", "安徽": "34", "福建": "35", "江西": "36", "山东": "37",
    "河南": "41", "湖北": "42", "湖南": "43", "广东": "44", "广西": "45",
    "海南": "46", "重庆": "50", "四川": "51", "贵州": "52", "云南": "53",
    "西藏": "54", "陕西": "61", "甘肃": "62", "青海": "63", "宁夏": "64",
    "新疆": "65"
  };
  
  // 支持简写
  const normalizedProvince = provinceName.replace(/[省市自治区]/g, "");
  return provinceMap[normalizedProvince] || provinceMap[provinceName];
}

// 设置外观 - 修复深色模式问题
function setupAppearance(widget) {
  // 使用动态颜色设置背景
  widget.backgroundColor = Color.dynamic(
    new Color("#FFFFFF"), // 浅色模式背景
    new Color("#000000")  // 深色模式背景
  );
}

// 添加油价网格
function addOilGrid(parentStack, oilData) {
  const colors = {
    "92#": "#34a853",
    "95#": "#ea4335",
    "98#": "#fbbc05",
    "0#": "#4285f4"
  };
  
  // 第一行（92# 和 95#）
  const row1 = parentStack.addStack();
  addOilItem(row1, "92#", findOilPrice(oilData, "92"), colors["92#"]);
  addOilItem(row1, "95#", findOilPrice(oilData, "95"), colors["95#"]);
  
  // 第二行（98# 和 0#）- 增加间距
  parentStack.addSpacer(4);
  const row2 = parentStack.addStack();
  addOilItem(row2, "98#", findOilPrice(oilData, "98"), colors["98#"]);
  addOilItem(row2, "0#", findOilPrice(oilData, "0"), colors["0#"]);
}

// 智能查找油价 - 增强版
function findOilPrice(oilData, oilType) {
  const provinceData = oilData?.provinceData || {};

  const exactKeyGroups = {
    "92": ["GAS_92", "GAS92", "92#", "92", "92号汽油", "92汽油"],
    "95": ["GAS_95", "GAS95", "95#", "95", "95号汽油", "95汽油"],
    "98": ["AIPAO_GAS_98", "GAS_98", "GAS98", "98#", "98", "98号汽油", "98汽油"],
    "0": ["CHECHAI_0", "CHE0", "DIESEL_0", "0#", "0号柴油", "0柴油", "柴油"]
  };

  const labelKeywords = oilType === "0"
    ? ["0号柴油", "柴油", "CHECHAI_0", "DIESEL_0", "0#"]
    : [`${oilType}号汽油`, `${oilType}汽油`, `${oilType}#`, `GAS_${oilType}`, `GAS${oilType}`];

  for (const key of exactKeyGroups[oilType] || []) {
    if (provinceData[key] !== undefined && provinceData[key] !== null) {
      const result = extractValue(provinceData[key]);
      if (result) return result;
    }
  }

  const visited = new Set();
  const result = searchPriceNode(provinceData, labelKeywords, visited);
  if (result) return result;

  return null;
}

function searchPriceNode(node, labelKeywords, visited) {
  if (node === null || node === undefined) return null;

  if (typeof node === "string" || typeof node === "number") {
    return extractValue(node);
  }

  if (Array.isArray(node)) {
    for (const item of node) {
      const result = searchPriceNode(item, labelKeywords, visited);
      if (result) return result;
    }
    return null;
  }

  if (typeof node === "object") {
    if (visited.has(node)) return null;
    visited.add(node);

    let labelMatched = false;
    for (const key of Object.keys(node)) {
      const keyText = String(key).toLowerCase();
      const val = node[key];
      const valText = typeof val === "string" ? val : "";

      if (labelKeywords.some(keyword => keyText.includes(keyword.toLowerCase()) || valText.includes(keyword))) {
        labelMatched = true;
      }
    }

    if (labelMatched) {
      const preferredKeys = [
        "price", "value", "oilPrice", "retailPrice", "currentPrice",
        "wholesalePrice", "salePrice", "latestPrice", "priceStr"
      ];
      for (const key of preferredKeys) {
        if (node[key] !== undefined) {
          const result = extractValue(node[key]);
          if (result) return result;
        }
      }
    }

    for (const key in node) {
      const child = node[key];
      const keyText = String(key).toLowerCase();

      if (labelKeywords.some(keyword => keyText.includes(keyword.toLowerCase()))) {
        const result = extractValue(child);
        if (result) return result;
      }

      const result = searchPriceNode(child, labelKeywords, visited);
      if (result) return result;
    }
  }

  return null;
}


// 从值中提取价格 - 增强版
function extractPriceString(text) {
  if (text === null || text === undefined) return null;

  const raw = String(text).replace(/,/g, "").trim();
  if (!raw) return null;

  const withUnit = raw.match(/(\d+(?:\.\d{1,2})?)(?=\s*(?:元\/升|元\/吨|元|\/升|\/吨))/);
  if (withUnit) {
    return normalizePrice(withUnit[1]);
  }

  const pureNumber = raw.match(/^\d+(?:\.\d{1,2})?$/);
  if (pureNumber) {
    const num = Number(pureNumber[0]);
    if (Number.isFinite(num) && num > 0 && num < 100) {
      return normalizePrice(pureNumber[0]);
    }
  }

  return null;
}

function normalizePrice(value) {
  const num = Number(value);
  if (!Number.isFinite(num)) return null;
  return num.toFixed(2).replace(/\.00$/, "");
}

function extractValue(value) {
  if (Array.isArray(value)) {
    for (const item of value) {
      const result = extractValue(item);
      if (result) return result;
    }
    return null;
  }

  if (typeof value === "object" && value !== null) {
    const preferredKeys = [
      "price", "value", "oilPrice", "retailPrice", "currentPrice",
      "wholesalePrice", "salePrice", "latestPrice", "priceStr"
    ];

    for (const key of preferredKeys) {
      if (value[key] !== undefined) {
        const result = extractValue(value[key]);
        if (result) return result;
      }
    }

    for (const key in value) {
      const result = extractValue(value[key]);
      if (result) return result;
    }
    return null;
  }

  if (typeof value === "string" || typeof value === "number") {
    return extractPriceString(value);
  }

  return null;
}


// 添加单个油价项目 - 优化显示空间（添加方块符号）
function addOilItem(parentStack, label, price, colorHex) {
  const itemStack = parentStack.addStack();
  itemStack.layoutVertically();
  itemStack.setPadding(5, 10, 5, 10); // 减少左右内边距
  
  // 创建标签堆栈（包含方块符号和文本）
  const labelStack = itemStack.addStack();
  labelStack.centerAlignContent();
  
  // 添加方块符号（使用油品颜色）
  const block = labelStack.addText("█"); // 方块符号
  block.font = Font.systemFont(18);
  block.textColor = new Color(colorHex);
  block.minimumScaleFactor = 0.5; // 允许缩放
  
  // 添加间距
  labelStack.addSpacer(4);
  
  // 添加标签文本
  const labelText = labelStack.addText(label);
  labelText.font = Font.boldSystemFont(16);
  labelText.textColor = new Color(colorHex);
  labelText.minimumScaleFactor = 0.5;
  
  // 添加价格
  let displayPrice = price ? `${price}元`: "N/A";
  const priceText = itemStack.addText(displayPrice);
  
  // 根据价格长度动态调整字体大小
  if (displayPrice.length > 6) {
    priceText.font = Font.boldSystemFont(20);
  } else {
    priceText.font = Font.boldSystemFont(24);
  }
  
  priceText.textColor = getTextColor(); // 使用主题文字颜色
  priceText.minimumScaleFactor = 0.5; // 允许文本缩小
  
  parentStack.addSpacer();
}

  
// 添加内嵌Logo，保持原有大小；解码异常时显示文字。
async function addLogo(parentStack) {
  try {
    const data = Data.fromBase64String(SINOPEC_LOGO_BASE64);
    if (!data) throw new Error("内嵌图标数据解码失败");
    const img = Image.fromData(data);
    if (!img) throw new Error("内嵌图标图片读取失败");
    const imgElem = parentStack.addImage(img);
    imgElem.imageSize = new Size(100, 100); // Logo
    imgElem.cornerRadius = 8;

  } catch (e) {
    const fallback = parentStack.addText("中石化");
    fallback.font = Font.boldSystemFont(10); // 缩小回退文本
    fallback.textColor = Color.red();
    parentStack.addSpacer(4);
  }

}

// 获取油价API - 修复版（从provinceData提取）
async function fetchOilPrice(provinceId) {
  const url = "https://cx.sinopecsales.com/yjkqiantai/data/switchProvince";
  const req = new Request(url);

  req.method = "POST";
  req.headers = {
    "Content-Type": "application/json;charset=UTF-8",
    "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15E148",
    "Referer": "https://cx.sinopecsales.com/web/customer/oilPrice.html"
  };
  req.body = JSON.stringify({ provinceId });

  try {
    const resp = await req.loadJSON();

    if (!resp || !resp.data) {
      throw new Error("API返回数据无效");
    }

    if (config.runsInApp) {
      console.log("完整API响应:");
      console.log(JSON.stringify(resp, null, 2));

      if (resp.data.provinceData) {
        console.log("省份油价数据 (provinceData):");
        console.log(JSON.stringify(resp.data.provinceData, null, 2));

        console.log("提取的油价:");
        console.log(`92#: ${findOilPrice(resp.data, "92")}`);
        console.log(`95#: ${findOilPrice(resp.data, "95")}`);
        console.log(`98#: ${findOilPrice(resp.data, "98")}`);
        console.log(`0#: ${findOilPrice(resp.data, "0")}`);
      }
    }

    return resp.data;
  } catch (error) {
    console.error(`油价请求失败: ${error}`);
    throw new Error("网络请求失败，请稍后重试");
  }
}


// 配置省份
async function configureProvince() {
  const alert = new Alert();
  alert.title = "设置油价省份";
  alert.message = "请输入省份名称和刷新频率（小时）";
  
  alert.addTextField("省份名称", "");
  alert.addTextField(`刷新频率(小时, 默认${DEFAULTS.refreshHours})`, DEFAULTS.refreshHours.toString());
  alert.addAction("确定");
  alert.addCancelAction("取消");
  
  const response = await alert.presentAlert();
  if (response === 0) { // 确定按钮
    const province = alert.textFieldValue(0).trim();
    let refreshHours = parseInt(alert.textFieldValue(1));
    
    // 验证刷新频率
    if (isNaN(refreshHours) || refreshHours <= 0) {
      refreshHours = DEFAULTS.refreshHours;
    }
    
    if (!province) {
      const errorAlert = new Alert();
      errorAlert.title = "输入无效";
      errorAlert.message = "省份名称不能为空";
      await errorAlert.presentAlert();
      return;
    }
    
    const provinceId = cityToId(province);
    if (!provinceId) {
      const errorAlert = new Alert();
      errorAlert.title = "省份不支持";
      errorAlert.message = `未找到省份: ${province}`;
      await errorAlert.presentAlert();
      return;
    }
    
    await saveConfig(province, refreshHours);
    
    // 测试获取油价
    try {
      const oilData = await fetchOilPrice(provinceId);
      const successAlert = new Alert();
      successAlert.title = "设置成功";
      successAlert.message = `已设置为: ${province}\n刷新频率: ${refreshHours}小时\n油价获取成功!`;
      await successAlert.presentAlert();
      
      // 显示预览
      const widget = new ListWidget();
      setupAppearance(widget);
      addOilGrid(widget, oilData);
      await widget.presentMedium();
    } catch (error) {
      const errorAlert = new Alert();
      errorAlert.title = "油价获取失败";
      errorAlert.message = `省份: ${province}\n错误: ${error.message}`;
      await errorAlert.presentAlert();
    }
  }
}

// 执行主函数或配置
if (config.runsInApp) {
  // 在App内运行时显示配置选项
  const alert = new Alert();
  alert.title = "油价小组件";
  alert.message = "请选择操作";
  alert.addAction("查看油价");
  alert.addAction("配置省份");
  alert.addCancelAction("取消");
  
  const response = await alert.presentAlert();
  if (response === 0) { // 查看油价
    const widget = await main();
    await widget.presentMedium();
  } else if (response === 1) { // 配置省份
    await configureProvince();
  }
} else {
  // 在小组件中直接运行
  await main();
}
